import { createHash } from "node:crypto";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";

const root = resolve(import.meta.dir, "..");
const localePath = resolve(root, "locales", "en.json");
const outputPath = resolve(root, "src", "generated", "messages.ts");

const raw = readFileSync(localePath, "utf8");
const catalog = JSON.parse(raw) as Record<string, string>;
const hash = createHash("sha256").update(raw).digest("hex");
const lines = [
  "// GENERATED by scripts/build-messages.ts from locales/en.json — do not edit by hand.",
  `export const CATALOG_HASH = "${hash}";`,
  "export const MESSAGES = {",
  ...Object.entries(catalog).map(([key, value]) => `  ${JSON.stringify(key)}: ${JSON.stringify(value)},`),
  "} as const;",
  "export type MessageKey = keyof typeof MESSAGES;",
  "",
];
mkdirSync(dirname(outputPath), { recursive: true });
writeFileSync(outputPath, lines.join("\n"), "utf8");
console.log(`wrote ${outputPath} (${Object.keys(catalog).length} messages)`);
